import{_ as o,l as r,o as a,c as l,v as c,p as i,x as s,d as p,i as d,S as n}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"seccomp 过滤","description":"","frontmatter":{"title":"seccomp 过滤","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/seccomp-filter.md","filePath":"cs/seccomp-filter.md","lastUpdated":1789023840000}'),m={name:"cs/seccomp-filter.md"};function h(E,e,B,_,u,f){const t=r("Mermaid");return a(),l("div",null,[e[1]||(e[1]=c('<h1 id="seccomp-过滤" tabindex="-1">seccomp 过滤 <a class="header-anchor" href="#seccomp-过滤" aria-label="Permalink to &quot;seccomp 过滤&quot;">​</a></h1><div class="epigraph"><p>seccomp 在系统调用入口按过滤器决定允许、拒绝或杀死；过滤器看到的是调用号与参数的受限视图，不是攻击脚本。</p><footer>—— 据 Linux seccomp(2)；内核文档对 BPF 过滤器的整理</footer></div><p><a href="/cs/container-os">上一课</a>仍把完整系统调用表暴露给容器内进程。<a href="/cs/syscall-path">系统调用路径</a> 在陷入后按号分发。缺口是<strong>调用号过滤器</strong>：在分发前截住，缩小内核攻击面。本课只讲机制与允许/拒绝结果，不讨论如何绕过过滤器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>容器切了 pid 与根，<code>mount</code>、<code>ptrace</code>、稀有 ioctl 仍可能到达同一内核。若用户态策略是「只许 read/write/exit」，需要内核强制。seccomp-BPF：进程安装过滤器，此后每次系统调用跑该程序，返回允许、ERRNO、KILL 等。strict 模式更粗（只许极少调用）。缺口不是罗列调用号清单，而是：过滤器是只读的、可继承的、安装后通常不可再放宽。</p><p><span class="marginnote">过滤器不能当通用沙箱替代：仍共享内核。参数检查能力有限，不能替代 IOMMU 或用户命名空间。本课不给示例去探测内核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>进程（或运行时在 exec 前）安装过滤器。陷入：硬件路径同前，内核在进入具体 syscall 实现前求值。允许则照常 copy 参数、执行；拒绝则不进入实现。与 ptrace 的对照：ptrace 可拦截但重、且用途是调试；seccomp 是声明式子集。容器运行时常用「默认拒绝 + 白名单」。</p>',8)),(a(),i(n,null,{default:s(()=>[d(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRAP%5B%22%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%E9%99%B7%E5%85%A5%22%5D%20--%3E%20FILT%5B%22seccomp%20%E8%BF%87%E6%BB%A4%E5%99%A8%22%5D%0A%20%20FILT%20--%3E%20OK%5B%22%E5%85%81%E8%AE%B8%3A%20%E5%8E%9F%E8%B7%AF%E5%BE%84%22%5D%0A%20%20FILT%20--%3E%20NO%5B%22%E6%8B%92%E7%BB%9D%2F%E6%9D%80%E6%AD%BB%3A%20%E4%B8%8D%E8%BF%9B%E5%85%A5%E5%AE%9E%E7%8E%B0%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=c('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>seccomp 把「谁可以请内核做什么」从「有 fd 和 uid」再收一层到「有哪些 syscall」。它发生在 <a href="/cs/syscall-path">syscall-path</a> 的门口，不改页表。与 setuid 不同：不提升身份，只减操作面。不能替代虚拟机：敏感特权指令若在用户态乱执行，仍是非法指令，不是 seccomp 的对象——下一课才把「客内核执行特权指令」当问题。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入每条 BPF 指令的编写教程当攻击工具。不讨论如何使过滤器失效。下一课真正的虚拟化：客机认为自己在环 0，宿主要在敏感指令上陷入并模拟。</p><p>后课默认：本机进程的 syscall 面可裁。客内核的特权指令如何交给宿主，下一课陷阱与模拟。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>seccomp 在 syscall 入口按过滤器允许或拒绝。</li><li>减面，不提供第二内核；本课无利用内容。</li><li>客机特权指令是 trap-and-emulate 的缺口。</li><li>出处：Linux <code>seccomp(2)</code>；内核 seccomp 文档。</li></ul>',7))])}const x=o(m,[["render",h]]);export{T as __pageData,x as default};
